mapper.select:
SELECT primary_key, enterprise_code, son_enterprise_code, seal_name, record_number, seal_type, template_type, center_star, data, seal_id, height, width, post_code_list, staff_code_list, enable_flag, create_time, update_time, delete_flag, seal_belong FROM ${tableName} WHERE delete_flag = false AND enterprise_code = #{enterpriseCode}
AND son_enterprise_code = #{sonEnterpriseCode}
AND son_enterprise_code IS NULL
order by create_time desc

mapper.update:
UPDATE ${tableName}
SET delete_flag = false

    , seal_name = #{seal.sealName}


    , record_number = #{seal.recordNumber}


    , template_type = #{seal.templateType}


    , seal_belong = #{seal.sealBelong}


    , data = #{seal.data}


    , seal_id = #{seal.sealId}


    , height = #{seal.height}


    , width = #{seal.width}


    , center_star = #{seal.centerStar}

WHERE delete_flag = false
AND primary_key = #{seal.sealCode}
AND enable_flag = true

UPDATE ${tableName}
SET post_code_list  = #{postCodes},
    staff_code_list = #{staffCodes}
WHERE delete_flag = false
  AND primary_key = #{sealCode}
  AND enable_flag = true

UPDATE ${tableName}
SET post_code_list = (SELECT array_agg(elem)
                      FROM unnest(post_code_list) AS elem(value)
                      WHERE elem.value <> #{postCode})
WHERE delete_flag = false
  AND enterprise_code = #{enterpriseCode}
